// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to exercise notDelegated modifier context (must be an EOA or arbitrary caller)
    function testFuzz_property(address caller) public {
        // keep wide domain but disallow the zero address to avoid degenerate cases where tooling treats specially
        vm.assume(caller != address(0));

        // call proxiableUUID as an external caller (not via delegatecall), which should succeed and return the UUID
        // We capture whether the call succeeds and the returned value. The correct contract always returns
        // the ERC1967 implementation slot value; the mutant will return bytes32(0) and thus differ for some input.

        bool ok;
        bytes32 uuid;
        // call from arbitrary caller
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32 v) {
            ok = true;
            uuid = v;
        } catch {
            ok = false;
            uuid = bytes32(0);
        }

        // The universal property we assert: the call must succeed (not revert) for all callers and return the ERC1967 slot.
        // We assert that the call succeeded and returned the canonical ERC1967 implementation slot.
        // This holds for the reference C for any caller; the mutant will sometimes return bytes32(0) instead,
        // causing this assertion to fail for those inputs.
        bytes32 expected = type(C).interfaceId == bytes4(0) ? bytes32(0) : C.proxiableUUID.selector; // dummy to avoid unused; replaced below

        // Read actual expected value by calling proxiableUUID in this execution context without try/catch to get the return
        // (we already have uuid and ok). For the assertion we require the call succeeded and returned the standard ERC1967 slot.
        // The canonical ERC1967 slot is the same constant used in the contract source: 0x3608...2bbc
        bytes32 ERC1967_IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

        assertTrue(ok && uuid == ERC1967_IMPLEMENTATION_SLOT);
    }
}

