pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address (to exercise different call contexts) and a bool to decide whether to call directly
    // The property: for any admissible caller, calling proxiableUUID() from that caller returns the canonical
    // ERC1967 implementation slot (observed via the returned bytes32) on the reference contract.
    function testFuzz_property(address caller, bool usePrank) public {
        // keep wide but avoid zero-address to be a bit more realistic
        if (caller == address(0)) caller = address(1);

        bytes32 slot;
        bool ok;

        // Call proxiableUUID from the fuzzed caller context when requested, otherwise call from this test contract
        if (usePrank) {
            // make sure the caller has some ETH so it's a non-empty EOA for realistic call
            vm.deal(caller, 1 wei);
            vm.prank(caller);
            try c.proxiableUUID() returns (bytes32 returned) {
                slot = returned;
                ok = true;
            } catch {
                // If it reverts, mark as not ok (but reference should not revert in normal contexts)
                ok = false;
            }
        } else {
            try c.proxiableUUID() returns (bytes32 returned) {
                slot = returned;
                ok = true;
            } catch {
                ok = false;
            }
        }

        // single assertion: on the correct contract, proxiableUUID() completes and equals the canonical slot
        // We assert that the call completed (ok) AND returned the ERC1967 implementation slot.
        // This will hold for the reference C for all inputs and fail for the mutant for some inputs
        // (the mutant returns bytes32(0) instead).
        bytes32 canonical = type(C).interfaceId == bytes4(0) ? bytes32(0) : bytes32(0); // dummy to satisfy shape; replaced below
        // We cannot access ERC1967Utils.IMPLEMENTATION_SLOT directly here, but the reference contract's proxiableUUID
        // returns that constant; therefore asserting equality to the returned value is sufficient. We assert equality to
        // slot itself (ensuring ok) and also that slot != bytes32(0) to distinguish mutant that returns zero.
        // Final single assertion required by the problem:
        assertTrue(ok && slot != bytes32(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to exercise both EOA and contract callers
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address which is less interesting
        vm.assume(caller != address(0));

        // We'll call proxiableUUID() from the fuzzed caller context. If caller is a contract
        // it can invoke the external call; if it's an EOA, we just impersonate it via vm.prank.
        // To ensure we can simulate a contract caller, deploy a tiny forwarder contract and
        // use it when the fuzzed address has codehash == 0 (i.e., is EOA). But we still let the
        // fuzzer choose the caller address to distinguish behaviors.

        // Deploy a simple caller contract that forwards calls to target. We'll use it when
        // caller is a contract; otherwise we'll just prank the EOA address directly.
        Forwarder f = new Forwarder();

        bool ok;
        // If the fuzzed address has code at it in the test environment, we can't impersonate that
        // exact address as a caller. We instead use either the deployed forwarder (a contract caller)
        // or the EOA impersonation via vm.prank. The fuzzer still provides the deciding bit (caller).
        // Use the parity of the supplied address to choose which calling context to exercise while
        // keeping the fuzzer parameter in the decision path.
        if (uint160(caller) % 2 == 0) {
            // simulate call from an EOA: impersonate the fuzzed address
            vm.prank(caller);
            try c.proxiableUUID() returns (bytes32 slot) {
                // the canonical implementation slot constant from ERC1967Utils in the real contract
                bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
                ok = (slot == expected);
            } catch {
                // if it reverts when called from this context, mark as not ok
                ok = false;
            }
        } else {
            // simulate a contract caller by having our forwarder invoke the function
            try f.callProxiable(address(c)) returns (bytes32 slot) {
                bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
                ok = (slot == expected);
            } catch {
                ok = false;
            }
        }

        // Single assertion: on the correct contract, every successful call must return the ERC1967 implementation slot.
        // This will hold for all inputs on the reference but the mutant that returns bytes32(0) will fail for some fuzzed inputs,
        // causing this assertion to fail.
        assertTrue(ok);
    }
}

// Minimal forwarder to act as a contract caller
contract Forwarder {
    function callProxiable(address target) external returns (bytes32 slot) {
        // forward the external call and return its bytes32 result
        (bool success, bytes memory ret) = target.call(abi.encodeWithSelector(bytes4(keccak256("proxiableUUID()"))));
        if (!success) revert();
        slot = abi.decode(ret, (bytes32));
    }
}

