pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz an arbitrary address to act as the accessControl admin passed to initialize.
    // General rule: after a successful initialize(admin) on the reference implementation,
    // calling proxiableUUID() directly (non-delegated call) should return the ERC1967 implementation slot
    // and NOT revert; the mutant that omits __UUPSUpgradeable_init() can make proxiableUUID() revert
    // because the notDelegated / __self checks behave differently. We expose this by calling proxiableUUID()
    // on the contract after initialize and asserting it returns the expected constant (no revert).
    function testFuzz_property(address admin) public {
        // avoid zero address for a more realistic admin but keep domain wide
        vm.assume(admin != address(0));

        // call initialize with fuzzed admin
        bool ok;
        try c.initialize(admin) {
            ok = true;
        } catch {
            // If initialize itself reverts for some admin due to access control logic elsewhere, treat as not ok
            ok = false;
        }

        // If initialize reverted, then proxiableUUID cannot be expected to succeed; we only assert when initialize succeeded.
        if (!ok) return;

        // Now call proxiableUUID() externally (this is a direct call, not delegatecall) and expect it to return the IMPLEMENTATION_SLOT
        // We must catch reverts; the buggy mutant will revert here for some inputs while the reference will succeed for all.
        bool suc;
        bytes32 slot;
        try c.proxiableUUID() returns (bytes32 s) {
            suc = true;
            slot = s;
        } catch {
            suc = false;
            slot = 0x0;
        }

        // The expected IMPLEMENTATION_SLOT value from ERC1967Utils in the reference is:
        // 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

        // Single assertion: proxiableUUID() must succeed and return expected slot for the correct contract
        assertTrue(suc && slot == expected);
    }
}

