pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the caller address: for the correct contract, after initialize any caller
    // can call proxiableUUID() (notDelegated check uses immutable __self set at deployment),
    // while the mutant that omits __UUPSUpgradeable_init() will revert for some callers.
    function testFuzz_property(address caller) public {
        // keep domain wide but exclude zero address to avoid trivial edge
        vm.assume(caller != address(0));

        // initialize the contract (use caller as the access control address parameter)
        // We let any address be the _accessControl parameter; the difference is in UUPS init.
        // call initialize from a privileged (EOA) account: use vm.prank to be that account
        vm.prank(address(1));
        c.initialize(caller);

        // Now attempt to call proxiableUUID() as `caller` (fuzzed). If the contract is the reference
        // it should allow this call (notDelegated check passes) and return the slot; if mutant omitted
        // UUPS init it can revert for some caller values. We only observe success/failure.
        bool ok;
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: for the correct contract this must be true for ALL callers,
        // while the mutant will be false for some caller the fuzzer will find.
        assertTrue(ok);
    }
}

