pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the bytes of a tiny helper init code that will create a contract which delegatecalls
    // into C to invoke proxiableUUID(); the property: when initialize succeeds on reference,
    // a delegatecall into C for proxiableUUID() must revert (notDelegated disallows delegatecalls);
    // the mutant (missing __UUPSUpgradeable_init) lets some delegatecall contexts behave differently
    // so the fuzzer can find a helper init code that makes the call not revert. We fuzz helper init code
    // as bytes (must be non-empty and reasonably short).
    function testFuzz_property(bytes memory initCode) public {
        // keep domain wide but non-empty and reasonably sized to allow creation
        vm.assume(initCode.length > 0 && initCode.length <= 200);

        // initialize c properly (reference requires initializer to succeed)
        address admin = address(this);
        bool ok;
        try c.initialize(admin) {
            ok = true;
        } catch {
            // If initialize reverts on reference for these inputs, exclude this case
            // (reference should accept any address), but be permissive: assume false
            vm.assume(false);
        }

        // Deploy a helper contract with provided initCode (adversarial counterpart) via create
        address helper;
        assembly {
            helper := create(0, add(initCode, 0x20), mload(initCode))
        }
        // creation may fail for some arbitrary bytes; those cases are not interesting
        vm.assume(helper != address(0));

        // The helper MUST attempt to delegatecall into c and return whether proxiableUUID succeeded.
        // We call the helper (which executes its runtime code) and read its success via try/catch low-level call.
        (bool success, ) = helper.call("");

        // The general rule: delegatecalling into implementation proxiableUUID must revert (notDelegated)
        // So success must be false for all admissible helper runtime codes. The buggy mutant will allow
        // some helper runtime codes to make this succeed. We assert that the helper call failed.
        assertTrue(!success);
    }
}

/*
Minimal note: The test crafts arbitrary initCode that becomes helper runtime code. The helper runtime
must attempt a delegatecall into c to invoke proxiableUUID(). For the reference contract C, such
delegatecall should revert due to notDelegated; for the mutant missing __UUPSUpgradeable_init, some
constructed helper runtimes may observe differing behavior and make the delegatecall succeed; the
fuzzer will search initCode bytes to find such a case and thus fail the mutant while this test passes
on the reference for all admissible initCode that lead to successful helper deployment.
*/

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: an arbitrary address to act as accessControl admin candidate and a boolean deciding whether
    // we call initialize from that admin (vm.prank) or from address(this). We keep domain wide.
    function testFuzz_property(address accessControl, bool fromPranked) public {
        // admissible domain: disallow zero-address for accessControl to avoid trivial reverts elsewhere
        vm.assume(accessControl != address(0));

        bool initOk;
        if (fromPranked) {
            // attempt to call initialize as accessControl (pranked caller)
            vm.prank(accessControl);
            try c.initialize(accessControl) {
                initOk = true;
            } catch {
                initOk = false;
            }
        } else {
            // call initialize from this test contract
            try c.initialize(accessControl) {
                initOk = true;
            } catch {
                initOk = false;
            }
        }

        // After a successful initialize on the reference, calling proxiableUUID() directly (non-delegated)
        // must NOT revert. We check: if initialize succeeded, then proxiableUUID() called directly should succeed.
        // We perform the call and set ok accordingly; then assert that initOk implies proxiableOk.
        bool proxiableOk;
        if (initOk) {
            // direct call to proxiableUUID() from this (non-delegated) context
            try c.proxiableUUID() returns (bytes32) {
                proxiableOk = true;
            } catch {
                proxiableOk = false;
            }
        } else {
            // if init failed, we don't require proxiable to succeed; set proxiableOk true so implication holds vacuously
            proxiableOk = true;
        }

        // Single assertion: whenever initialize(...) succeeded, proxiableUUID() must be callable (non-reverting)
        assertTrue(!initOk || proxiableOk);
    }
}

