pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerSimulator {
    // helper that will call target.proxiableUUID() and bubble up success/failure
    function callProxiable(address target) external returns (bool ok, bytes memory data) {
        (ok, data) = target.call(abi.encodeWithSignature("proxiableUUID()"));
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the helper address salt so the fuzzer explores different adversarial helper deployments
    function testFuzz_property(uint256 deploySalt) public {
        // Keep domain wide but bound to a practical range to avoid out-of-gas when creating huge contracts
        deploySalt = bound(deploySalt, 0, type(uint32).max);

        // initialize must succeed for both reference and mutant; choose an arbitrary accessControl (EOA)
        address accessControl = address(0x1234);
        bool ok;
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            ok = false;
        }
        // require initialize succeeded; both reference and mutant should allow initialize with any accessControl
        assertTrue(ok);

        // Deploy a helper with varying salt to create different code/address shapes
        // Use create2 with simple creation code to vary the resulting caller contract
        bytes memory creation = type(CallerSimulator).creationCode;
        address helper;
        assembly {
            helper := create2(0, add(creation, 0x20), mload(creation), deploySalt)
        }
        // If deployment failed for some salts (very unlikely), deploy normally
        if (helper == address(0)) {
            helper = address(new CallerSimulator());
        }

        // Now have the helper call c.proxiableUUID() via low-level call; capture whether it reverted
        CallerSimulator caller = CallerSimulator(helper);
        (bool success, ) = caller.callProxiable(address(c));

        // GENERAL RULE (single assertion): After initialize(...) completes, an external CALL into c that invokes
        // proxiableUUID() must NOT revert. The reference C always satisfies this for any helper address; the
        // mutant (omitting __UUPSUpgradeable_init) will cause proxiableUUID to revert for some helper deployments.
        assertTrue(success);
    }
}

