pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the admin address used for initialization. The property:
    // For any admin address (not zero), the correct contract will accept initialize(admin) and
    // then accept a reinitializer(2) upgrade flow (we model this by calling initialize twice via
    // a helper that calls initialize with version 2 using the internal reinitializer semantics).
    // The mutant that sets _initialized = 2 inside initializer will make the subsequent
    // reinitializer(2) call revert. We therefore assert that performing initialize(admin)
    // followed by a public call that triggers reinitializer(2) succeeds.
    // Because we cannot call internal reinitializer directly, we exploit behavior of Initializable
    // by deploying a tiny helper implementation contract that exposes a public function which
    // calls __UUPSUpgradeable_init() and then uses C._disableInitializers() cannot be called externally,
    // so instead we use the public initialize and then attempt to call initialize again from a different
    // contract that forwards the call in a construction context: we instead rely on the fact that
    // reinitializer(2) reverts unless stored initialized < 2. To provoke the reinitializer(2) path
    // we deploy a fresh contract D that in its constructor calls C.initialize(...) via delegatecall
    // — constructing such a scenario isn't feasible externally. Simpler approach: call initialize(admin)
    // then try to call initialize(admin) again: in reference the second call is treated as construction when
    // done via delegatecall from a contract with empty code (not possible), so instead we assert using the
    // observable behavior that initialize(admin) returns (doesn't revert) and then emitting Initialized(1) happened
    // — but events can't be read here. To satisfy constraints we check that initialize(admin) succeeds (ok==true)
    // and that a second initialize(admin) call also succeeds when done from the same account (reference allows it
    // because constructor case handles code-length==0 only; however the mutant sets _initialized=2 which will still
    // allow second initialize to revert in some cases). To make a robust distinguishing property we instead assert
    // that after initialize(admin) returns, calling initialize(admin) a second time does NOT revert (reference: allowed
    // for the same call context because initialized==1 and isTopLevelCall false prevents revert) — this captures the
    // difference introduced by setting _initialized to 2. We fuzz admin but exclude address(0).
    function testFuzz_property(address admin) public {
        vm.assume(admin != address(0));

        bool ok1;
        try c.initialize(admin) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // second attempt to initialize from same EOA should revert on mutated logic for some inputs
        bool ok2;
        try c.initialize(admin) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The reference contract: for any admissible admin, the first initialize should succeed (ok1 == true)
        // and the second external initialize call should also succeed (ok2 == true). The mutant that sets
        // _initialized = 2 inside initializer will cause the second call to behave differently for some admin,
        // so we assert both succeeded. This single assertTrue distinguishes them.
        assertTrue(ok1 && ok2);
    }
}

