pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz caller and kink to find an unauthorized caller that the reference rejects but the mutant accepts
    function testFuzz_property(address caller, uint256 kink) public {
        // keep kink in plausible non-extreme domain but allow wide space
        vm.assume(kink > 0 && kink < type(uint256).max);

        // prepare slope struct bytes: SlopeData{uint256 kink; uint256 slope0; uint256 slope1}
        // We'll craft calldata to call setSlopes externally as an arbitrary caller via vm.prank.

        // Build SlopeData: use kink from fuzz, leave slopes zero (valid as long as kink not 0 and <1e27)
        // But to ensure invalid kink triggers revert in reference when unauthorized? The access check happens first in reference,
        // so an unauthorized caller will revert due to AccessDenied. We need kink valid to reach access check outcome consistently.
        uint256 validKink = kink % 1e27; // ensure <1e27
        if (validKink == 0) {
            validKink = 1; // ensure non-zero
        }

        // Compose calldata for setSlopes(address _asset, SlopeData memory _slopes)
        // function selector
        bytes4 sig = bytes4(keccak256("setSlopes(address,(uint256,uint256,uint256))"));
        // asset address: use address(0x123) as arbitrary asset
        address asset = address(0x123);

        // encode calldata
        bytes memory slopesEncoded = abi.encode(validKink, uint256(0), uint256(0));
        bytes memory data = abi.encodePacked(sig, abi.encode(asset, slopesEncoded));

        // call setSlopes as fuzzed caller
        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call(data);
        ok = success;

        // General rule to assert: reference contract requires access control, so an arbitrary caller (not the configured access controller)
        // will NOT be able to call setSlopes; therefore for many callers the call should revert on the reference but will succeed on mutant.
        // We assert that the call did NOT succeed (i.e., reference enforces access) for this fuzzed caller.
        // This assertion must hold on the reference for all inputs; the mutant (without checkAccess) will allow some callers and thus fail this assert.
        assertTrue(!ok);
    }
}
